import TagManager from 'react-gtm-module'
import Cookies from 'universal-cookie'
import { hotjar } from 'react-hotjar'

const browserCookies = new Cookies()
const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard')
const loadGoogleTagManager = (currentOrg, profile) => {
  TagManager.initialize({
    gtmId: process.env.GTM,
    dataLayer: {
      organizationName: currentOrg && currentOrg.OrganizationName,
      organizationId: currentOrg && currentOrg.organizationID,
      userId: profile && profile['_id'],
      email: profile && profile.email,
    },
  })
}

const initializeHotjar = () => {
  typeof window !== 'undefined' && hotjar.initialize(process.env.HOTJAR_ID);
}

const initializeMatomo = () => {
  // eslint-disable-next-line no-underscore-dangle, no-multi-assign
  const _paq = window._paq = window._paq || [];
  /* tracker methods like "setCustomDimension" should be called before "trackPageView" */
  _paq.push(["setCookieDomain", "*.www.uxcam.com"]);
  _paq.push(['trackPageView']);
  _paq.push(['enableLinkTracking']);
  (function() {
    const u="https://uxcam.matomo.cloud/";
    _paq.push(['setTrackerUrl', `${u}matomo.php`]);
    _paq.push(['setSiteId', '1']);
    const d=document; const g=d.createElement('script'); const s=d.getElementsByTagName('script')[0];
    g.async=true; g.src='//cdn.matomo.cloud/uxcam.matomo.cloud/matomo.js'; s.parentNode.insertBefore(g,s);
  })();
}

const initializeIntercom = () => {
  if (typeof window !== 'undefined' && (cookieFromAdmin === null || cookieFromAdmin === undefined)) {
    const w = window
    const ic = w.Intercom
    if (typeof ic === 'function') {
      ic('reattach_activator')
      ic('update', w.intercomSettings)
    } else {
      const d = document
      const i = function () {
        i.c(arguments)
      }
      i.q = []
      i.c = function (args) {
        i.q.push(args)
      }
      w.Intercom = i
      const l = function () {
        const s = d.createElement('script')
        s.type = 'text/javascript'
        s.async = true
        s.src = `https://widget.intercom.io/widget/${process.env.INTERCOM_APP_KEY}`
        const x = d.getElementsByTagName('script')[0]
        x.parentNode.insertBefore(s, x)
      }
      if (document.readyState === 'complete') {
        l()
      } else if (w.attachEvent) {
        w.attachEvent('onload', l)
      } else {
        w.addEventListener('load', l, false)
      }
    }
  }
}

const initializeJiraWidget = () => {
  if (typeof window !== 'undefined') {
    const d = document;

    const loadJiraScript = () => {
      if (!d.querySelector('script[data-jsd-embedded]')) { // Avoid adding the script multiple times
        const script = d.createElement('script');
        script.src = 'https://jsd-widget.atlassian.com/assets/embed.js';
        script.setAttribute('data-jsd-embedded', 'true');
        script.setAttribute('data-key', process.env.JIRA_DATA_KEY);
        script.setAttribute('data-base-url', 'https://jsd-widget.atlassian.com');
        d.head.appendChild(script);
      }
    };

    if (d.readyState === 'complete' || d.readyState === 'interactive') {
      loadJiraScript();
    } else {
      d.addEventListener('DOMContentLoaded', loadJiraScript);
    }
  }
};

export {
  loadGoogleTagManager,
  initializeIntercom,
  initializeHotjar,
  initializeMatomo,
  initializeJiraWidget,
}
