import React, { memo } from 'react';

import styled from 'styled-components';

const SpinnerContainerFull = styled.div`
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
    margin: auto;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
    z-index: 9999;
`

const SpinnerContainer = styled.div`
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: auto;
`

const Spinner = styled.span`
  display: inline-block;
  font-size: 30px;
  padding: 0.8em;
  position: relative;
  width: 0.1em;
	height: 0.1em;
	color: inherit;
	vertical-align: middle;
	pointer-events: none;
  
  border: .3em solid #DFEAFF;
	border-top-color: #3377fa;
	border-radius: 50%;
	animation: 1s loader-spin linear infinite;
	position: relative;
	&:before {
		content: '';
		display: block;
		width: inherit;
		height: inherit;
		position: absolute;
		top: -.2em;
		;
		left: -.2em;
		;
		border: .2em solid transparent;
		border-radius: 50%;
		opacity: .5;
	}

  @keyframes loader-spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
`

const ReactLoader = memo(({ size, fullscreen, className }) => (
  fullscreen ? (
    <SpinnerContainerFull className={`loader center-loader ${className}`} >
      <Spinner 
      style={{
        fontSize: size ? `${size}px` : '30px'
      }}
    />
    </SpinnerContainerFull>
  ) :
  (
    <SpinnerContainer className={className || ''}>
      <Spinner 
      style={{
        fontSize: size ? `${size}px` : '30px'
      }}
      />
    </SpinnerContainer>
  )
));
export default ReactLoader
