import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import dynamic from 'next/dynamic';
import { CheckCircleTwoTone } from '@ant-design/icons';
import fetch from 'isomorphic-fetch';
import mixpanel from 'mixpanel-browser';
import {
  loadGoogleTagManager,
  initializeIntercom,
  initializeHotjar,
  initializeMatomo,
} from 'Utils/helpers/initializePlugins';
import MainHead from 'components/IntegratePages/layout/dashboardMenu/head';
import Source from 'components/common/referrerSource';
import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import { changeUrl, changeCommonValue } from 'redux/actions/common';
import { setKeyByValue } from 'redux/actions/auth';
import { isProd, headTitlePrefix } from 'Utils/constants/variables';
import ReactLoader from 'components/common/reactLoading';
import textToCheck from 'Utils/helpers/textToCheck';
import validateEmail from 'Utils/helpers/validateEmail';
import { GoogleOAuthProvider } from '@react-oauth/google';

const DashboardAccess = dynamic(import('components/common/dashboardAccess'), {
  loading: () => <ReactLoader fullscreen />,
});
const Error = dynamic(import('./_error'), {
  loading: () => <ReactLoader fullscreen />,
});
const Login = dynamic(import('components/features/onboard/Login/index'), {
  loading: () => <ReactLoader fullscreen />,
});
const SignupNewFlow = dynamic(import('components/features/onboard/SignUpFlow'), {
  loading: () => <ReactLoader fullscreen />,
});
const ResetPassword = dynamic(import('components/features/onboard/ResetPassword'), {
  loading: () => <ReactLoader fullscreen />,
});
const SetupPassword = dynamic(import('components/features/onboard/SetupPassword'), {
  loading: () => <ReactLoader fullscreen />,
});
const ResendActivation = dynamic(import('components/features/onboard/ResendActivation'), {
  loading: () => <ReactLoader fullscreen />,
});

const headTitle = {
  signup: 'UXCam Signup',
  signup_offer: 'UXCam Signup',
  login: 'UXCam Login',
  reset_password: 'Password Reset',
  setup_password: 'Set Password',
  resend_activation: 'The activation link has expired',
};
const components = {
  signup_offer: SignupNewFlow,
  signup: SignupNewFlow,
  login: Login,
  reset_password: ResetPassword,
  setup_password: SetupPassword,
  resend_activation: ResendActivation,
};

const Setup = (props) => {
  const dispatch = useDispatch();
  const {
    urlReducer: urlParam,
    auth: _auth,
    commonReducer
  } = useSelector((state) => state);

  const { parentType, url, statusCode, isResetError, reqQueries } = props;
  const { isActivation } = _auth;
  const { message } = _auth;
  const { isVisible_custom_popup } = commonReducer;

  const changeCommonValueDispatcher = (key, value) =>
    dispatch(changeCommonValue(key, value));
  const _setKeyByValue = (key, value) => dispatch(setKeyByValue(key, value));
  const newParentType =
    parentType ||
    (url && url?.query && url?.query?.parentType) ||
    urlParam?.parentType;

  const titleByParentType = headTitle[newParentType];
  const titleByEnv = headTitlePrefix[process.env.APP_ENV];
  const headTitleByEnv = `${titleByEnv}${titleByParentType}`;

  let changedEmail;
  if (
    reqQueries?.v &&
    reqQueries?.t === 'email' &&
    reqQueries?.a === 'changed'
  ) {
    const buff = new Buffer(reqQueries?.v, 'base64');
    changedEmail = buff.toString('ascii');
  }
  useEffect(() => {
    let signupApp = ''
    try {
      signupApp = localStorage.getItem('signupApp')
      localStorage.clear();
      if (signupApp) {
        localStorage.setItem('signupApp', signupApp)
      }
    } catch (err) {
      // silent fail
    }

    if (isProd && newParentType !== 'reset_password') { // GSB-181 reset password is not tracked because of token leaks
      initializeIntercom();
      if (typeof window.Intercom !== 'undefined') {
        const horizontalPadding = 0; // No AI Differentation in setup page
        window.Intercom && (
          window.Intercom('boot', {
            app_id: process.env.INTERCOM_APP_KEY,
            api_base: 'https://api-iam.intercom.io',
            alignment: 'right',
            horizontal_padding: horizontalPadding,
            hide_default_launcher: false,
          })
        )
      }
      initializeMatomo()
      mixpanel.init(process.env.MIXPANEL);
      mixpanel.track('Page Visited', {
        pageName: newParentType,
        pageURL: window.location.href,
      });
      mixpanel.register({
        source: Source(),
      });
      loadGoogleTagManager();
      initializeHotjar();
    }
  });
  if (statusCode) {
    return (
      <Error
        statusCode={statusCode}
        message={props.message}
        isResetError={isResetError}
      />
    );
  }
  const RenderComponent = components[newParentType];
  return (
    <GoogleOAuthProvider clientId={ process.env.GOOGLE_CLIENT_ID }>
      <MainHead
        hubSpotLink={
          newParentType === 'signup' &&
          `//js.hs-scripts.com/${process.env.HUBSPOT_ID}.js`
        }
        headTitle={
          statusCode
            ? `${mapToObject[process.env.APP_ENV]}Error`
            : headTitleByEnv
        }
      />
      {reqQueries?.t === 'email' && reqQueries?.a === 'changed' ? (
        <DashboardAccess
          headerMsg="You have successfully changed the email!"
          reasonNoDashboardAccess={
            <span>
              Your new email is <em>{changedEmail}</em>. Please use this email
              to login.
            </span>
          }
          id="isLogin"
          direct
          imgSrcLink={
            <CheckCircleTwoTone
              twoToneColor="#52c41a"
              style={{ fontSize: 60 }}
            />
          }
          isSrcElement
        />
      ) : (
        <div className="onboard-form-wrapper theme-light">
          <RenderComponent
            mixpanel={mixpanel}
            isVisible_custom_popup={isVisible_custom_popup}
            isActivation={isActivation}
            message={message}
            _auth={_auth}
            changeCommonValue={changeCommonValueDispatcher}
            setKeyByValue={_setKeyByValue}
            urlParam={url || urlParam}
            {...props}
          />
        </div>
      )}
    </GoogleOAuthProvider>
  );
};
Setup.getInitialProps = async ({ store, req, res }) => {
  const reqQueries = req?.query;
  let parentType =
    reqQueries?.parentType ||
    (store && store.getState().urlReducer.parentType) ||
    'login';
  if ( req && req.route ) {
    if (req.route.path.includes('signup')) {
      parentType = 'signup'
    } else if (req.route.path.includes('login')) {
      parentType = 'login';
    }
  }
  if (parentType)
    await store.dispatch(
      changeUrl({
        parentType,
        url: `/${parentType}`,
      })
    );
  let token;
  let redirectUrl;
  let webEmail;
  let googleLogin;
  let response;
  let json = {};
  let statusCode;
  let errorMessage;
  let isResetError;
  let returnObj;
  let isFromUXCamWebsite;
  let invitationToken;
  let secret;

  if (req) {

    token =  req?.params?.token || '';
    secret =  req?.params?.secret || '';
    invitationToken = req.query && req.query.invitation_token;
    redirectUrl = req.query.redirect || '';
    if (req.query.email || req?._parsedUrl?.query?.includes('e=')) {
      let str =
        req._parsedUrl &&
        req._parsedUrl.query &&
        req._parsedUrl.query.includes('e=')
          ? req._parsedUrl.query
          : req.query.email.replace('%40', '@');
      str = str.includes('e=') && str.split('=')[1];
      webEmail = str;
    }
    if (req.query.googleLogin) {
      googleLogin = true;
    }
  }
  if (token || secret) {
    if (req.cookies.token) {
      return res.redirect('/dashboard');
    }
    if (req?._parsedUrl?.query?.includes('secret')) {
      if (parentType === 'login') {
        response = await fetch(
          `${process.env.AUTH_API_URL}/team/invite/login/secret/${secret}`,
          { credentials: 'include' }
        );
      } else {
        await store.dispatch(
          changeUrl({ parentType: 'signup', url: '/setup' })
        );
        response = await fetch(
          `${process.env.AUTH_API_URL}/team/invite/signup/secret/${secret}`,
          {
            credentials: 'include',
          }
        );

        parentType = 'signup';
        !invitationToken &&
          (await store.dispatch(setKeyByValue('onBoardVisible', true)));
      }
    } else if (parentType === 'login') {
        response = await fetch(
          `${process.env.API_URL}/team/login/token/${token}`,
          { credentials: 'include' }
        );
      } else if (parentType === 'reset_password') {
        response = await fetch(
          `${process.env.AUTH_API_URL}/user/forgot-password/${ token }/confirm`,
          { credentials: 'include' }
        );
      } else {
        await store.dispatch(
          changeUrl({ parentType: 'signup', url: '/setup' })
        );
        response = invitationToken
          ? await fetch(
              `${process.env.AUTH_API_URL}/user/invitation/signup/${invitationToken}`,
              {
                credentials: 'include',
              }
            )
          : await fetch(`${process.env.API_URL}/team/signup/token/${token}`, {
              credentials: 'include',
            });
        parentType = 'signup';
        !invitationToken &&
          (await store.dispatch(setKeyByValue('onBoardVisible', true)));
      }
    json = await response?.json();
    // Admin invitations carry the dashboard surface they were issued for
    // (data.signupSurface). If this invite targets Tara, hand the click over
    // to its canonical Tara link instead of signing the user up through the
    // app surface. Only redirect to a different host so bad invitation data
    // cannot loop back here.
    if (
      invitationToken &&
      json?.data?.signupSurface === 'tara' &&
      json?.data?.invitationLink
    ) {
      try {
        const inviteUrl = new URL(json.data.invitationLink);
        if (inviteUrl.host && inviteUrl.host !== req?.headers?.host) {
          if (res) {
            return res.redirect(inviteUrl.href);
          }
          window.location.assign(inviteUrl.href);
          return {};
        }
      } catch (error) {
        console.error('error-on-invitation-surface-redirect', error);
      }
    }
    if (json?.error) {
      statusCode = json.error.status || 400;
      errorMessage = json.error.message || 'Something went wrong';
      isResetError = true;
    }
    try {
      if (res && response?.headers.get('set-cookie')) res.setHeader('set-cookie', response?.headers.get('set-cookie'));
    } catch (error) {
      console.error('error-on-setup', error)
    }
    returnObj = {
      csrf: (json?.data && json?.data.csrf && json?.data.csrf.token) || '',
      teamData: invitationToken ? null : json?.data,
      token,
      secret,
      redirectUrl,
      organization: (json?.data && json?.data.organization) || '',
      customer: (json?.data && json?.data.customer) || '',
      userInfo: json?.data,
      statusCode,
      message: errorMessage,
      isResetError,
      parentType,
      isEmailInvitation: !!invitationToken,
      invitationData: invitationToken ? json?.data : null,
      invitation_token: invitationToken,
    };
    return returnObj;
  }
  if (req) {
    if (req.cookies.token) {
      const queryRedirectUrl = req?.query?.redirect;
      if (queryRedirectUrl) {
        if (queryRedirectUrl.startsWith('/') && !validateEmail(queryRedirectUrl)) {
          return redirectUrlHandler(queryRedirectUrl, res);
        }
        const isValidRedirectUrl = textToCheck(queryRedirectUrl);
        const type = isValidRedirectUrl[0]?.text
          ? isValidRedirectUrl[0]?.type
          : isValidRedirectUrl[1]?.type;
        if (type === 'text' && !validateEmail(queryRedirectUrl)) {
          return redirectUrlHandler(queryRedirectUrl, res);
        }
      }
      return res.redirect('/dashboard');
    }
    if (parentType === 'login') {
      response = await fetch(`${process.env.API_URL}/auth/login`, {
        credentials: 'include',
      });
    }
    if (parentType.includes('signup')) {
      response = await fetch(`${process.env.API_URL}/auth/signup`, {
        credentials: 'include',
      });
      if (req.query.type === 'email_activation') {
        store.dispatch(setKeyByValue('isActivation', true));
        if (req.query.message) {
          const buff = new Buffer(req.query.message, 'base64');
          const text = buff.toString('ascii');
          store.dispatch(setKeyByValue('message', text));
        }
      }
       json = response && (await response.json());
      if (json?.error) {
        statusCode = json.error.status;
        errorMessage = json.error.message || 'Something went wrong';
        isResetError = true;
      }
    }
    try {
      if (res && response?.headers.get('set-cookie')) res.setHeader('set-cookie', response?.headers.get('set-cookie'));
    } catch (error) {
      console.error('error-on-setup', error)
    }
    if (
      req._parsedUrl &&
      req._parsedUrl.query &&
      req._parsedUrl.query.includes('e=') &&
      req._parsedUrl.query.split('=')[0] === 'e'
    ) {
      await store.dispatch(
        changeUrl({ parentType: 'signup', url: '/setup' })
      );
      parentType = 'signup';
      const buff = new Buffer(webEmail, 'base64');
      webEmail = buff.toString('ascii');
      isFromUXCamWebsite = true;
    }
    if (req.query.parentType === 'shortUrl') {
      parentType = 'login';
      redirectUrl = `${redirectUrl}&parentType=shortUrl${req.query.appId ? `&appId=${req.query.appId}` : ''}&id=${req.query.id}`;
    }
    if (response?.status === 503) {
      return res.redirect('/error?errorStatus=503');
    }
    returnObj = {
      csrf: json && json?.data && json?.data.csrf.token,
      token,
      secret,
      redirectUrl,
      webEmail,
      googleLogin,
      statusCode,
      message: errorMessage,
      isResetError,
      parentType,
      isFromUXCamWebsite,
      reqQueries,
    };
    return returnObj;
  }
};
export default Setup;
